const config = {
  appId: "test.campus.app",
  server: { hostname: "campus.test" },
  plugins: {
    App: {
      appUrlOpen: true,
      allowNavigation: ["*"]
    }
  }
};

App.addListener("appUrlOpen", function (event) {
  const url = new URL(event.url);
  if (url.pathname === "/order") {
    router.push("/order/" + url.searchParams.get("id"));
  } else {
    window.location.href = url.searchParams.get("redirect");
  }
});
